-- ============================================================
-- SEED: правила подбора материала/принтера для деталей БПЛА
-- по классу применения и условиям эксплуатации.
--
-- ВАЖНО (перенесено из оригинала без изменений по сути): данные ниже —
-- обобщённая типовая инженерная практика сообщества любительского и
-- мелкосерийного дроностроения (FPV/fixed-wing/multirotor), не цитаты
-- конкретных статей. Все source_type = 'community_practice' с url = NULL.
-- Перед производственным использованием — проверить/актуализировать
-- под реальные условия и, по возможности, привязать реальные ссылки
-- (source_type = 'forum_thread' / 'manufacturer_datasheet').
--
-- Адаптировано из ../../../../../../БД НСИ Аддитив/seed/seed_application_rules.sql
-- ============================================================

