(3, 'community_practice', 'Практика применения нейлона (PA) для нагруженных вращающихся/резьбовых деталей в FDM/SLS', NULL, 'medium', NULL);

-- ============================================================
-- Рекомендации материал+технология по классу детали и условиям
-- ============================================================

-- 1. Носовой обтекатель — высокая скорость потока, УФ, удар
--    -> ASA (аналог ABS, но с UV-стойкостью) основной вариант; PETG как более доступная альтернатива
INSERT INTO application_material_recommendation
(part_application_class_id, operating_condition_id, am_material_group_id, am_technology_id, priority, min_infill_percent, recommended_wall_count, orientation_note, recommendation_source_id, rationale) VALUES
(1, 6, 4, 1, 1, 30, 4, 'Печатать носом вверх (вдоль оси Z), чтобы линии слоёв не совпадали с плоскостью удара',
   1, 'ASA обладает УФ-стойкостью и более высокой теплостойкостью (HDT ~95°C) по сравнению с PLA/PETG, устойчив к деформации от аэродинамического нагрева на скорости, не желтеет и не охрупчивается на солнце при длительной эксплуатации на улице.'),
(1, 6, 2, 1, 2, 30, 4, NULL,
   1, 'PETG — более доступная и простая в печати альтернатива ASA, приемлемая ударная вязкость, но заметно уступает по УФ-стойкости при долгой эксплуатации на солнце — рекомендуется только для нечастых полётов или дневного использования без долгого хранения на улице.'),
(1, 8, 4, 1, 1, 30, 4, NULL,
   1, 'При подтверждённой длительной эксплуатации на открытом воздухе ASA — предпочтительный выбор среди FDM-материалов именно из-за встроенной UV-стабильности полимера (в отличие от PLA/PETG).');

-- 2. Корпус (фюзеляж) — умеренные нагрузки, УФ, вместимость электроники
INSERT INTO application_material_recommendation
(part_application_class_id, operating_condition_id, am_material_group_id, am_technology_id, priority, min_infill_percent, recommended_wall_count, orientation_note, recommendation_source_id, rationale) VALUES
(2, NULL, 2, 1, 1, 15, 3, NULL,
   1, 'PETG — стандартный выбор для корпусов дронов: хорошая ударная вязкость и жёсткость, проще в печати чем ASA/ABS (меньше warping, не требует обязательной закрытой камеры), достаточная прочность для несиловых панелей корпуса.'),
(2, 8, 4, 1, 2, 15, 3, NULL,
   1, 'Если корпус долго эксплуатируется на улице под солнцем — ASA предпочтительнее PETG по UV-стойкости, ценой чуть более сложной печати (желательна закрытая камера из-за усадки).'),
(2, NULL, 8, 2, 3, NULL, NULL, 'Актуально для мелкой детализации корпуса (антенные держатели, декоративные элементы)',
   1, 'SLA/DLP даёт значительно более высокую детализацию и чистоту поверхности, чем FDM — оправдано для небольших корпусных элементов со сложной геометрией, но смолы обычно более хрупкие и хуже держат ударную нагрузку, чем PETG/ASA.');

-- 3. Крыло/консоль — изгибающая нагрузка, скорость потока
INSERT INTO application_material_recommendation
(part_application_class_id, operating_condition_id, am_material_group_id, am_technology_id, priority, min_infill_percent, recommended_wall_count, orientation_note, recommendation_source_id, rationale) VALUES
(3, 5, 2, 1, 1, 20, 4, 'Печатать вдоль размаха крыла (длинной стороной по X/Y стола) — направление слоёв должно совпадать с направлением основной изгибающей нагрузки, а не быть перпендикулярным ей',
   1, 'PETG обеспечивает баланс жёсткости и ударной вязкости для консолей крыла средней скорости; ориентация печати вдоль размаха критична — печать поперёк резко снижает сопротивление изгибу по слоям (типичная причина разрушения печатных крыльев).'),
(3, 6, 4, 1, 1, 25, 4, 'Печатать вдоль размаха крыла',
   1, 'На высоких скоростях (>150 км/ч) аэродинамический нагрев передней кромки и повышенные аэродинамические нагрузки требуют более теплостойкого материала — ASA предпочтительнее PETG в этом диапазоне.');

-- 4. Винт (пропеллер) — усталостная и центробежная нагрузка, критична балансировка
--    Печатные винты в любительской практике встречаются реже готовых карбоновых/нейлоновых,
--    но при печати именно нейлон (PA) — стандартная рекомендация из-за усталостной прочности
INSERT INTO application_material_recommendation
(part_application_class_id, operating_condition_id, am_material_group_id, am_technology_id, priority, min_infill_percent, recommended_wall_count, orientation_note, recommendation_source_id, rationale) VALUES
(4, 10, 6, 1, 1, 100, 6, 'Печатать плашмя минимальным числом слоёв по толщине лопасти, направление слоёв — избегать совпадения плоскости расслоения с плоскостью изгиба лопасти',
   3, 'Полиамид (нейлон) обладает значительно более высокой усталостной прочностью и сопротивлением ударным нагрузкам по сравнению с PLA/PETG/ABS, что критично для детали, работающей на циклическую центробежную и изгибающую нагрузку тысячи циклов за полёт — это основная причина, почему нейлон типовая рекомендация сообщества для печатных винтов, а не PLA/PETG.'),
(4, 10, 12, 4, 2, 100, NULL, NULL,
   3, 'SLS-печать нейлоном (PA12) даёт изотропные механические свойства (в отличие от FDM, где прочность на межслойный разрыв ниже, чем в плоскости слоя) — предпочтительнее для нагруженных вращающихся деталей при наличии доступа к SLS.');

-- 5. Кронштейн навески — вибрация + удар
INSERT INTO application_material_recommendation
(part_application_class_id, operating_condition_id, am_material_group_id, am_technology_id, priority, min_infill_percent, recommended_wall_count, orientation_note, recommendation_source_id, rationale) VALUES
(5, 10, 6, 1, 1, 40, 4, NULL,
   3, 'Нейлон устойчив к усталостному разрушению под вибрацией и хорошо держит ударную нагрузку — предпочтителен для кронштейнов, напрямую или близко закреплённых к раме рядом с двигателями.'),
(5, 11, 2, 1, 2, 40, 4, NULL,
   1, 'PETG как более простая в печати альтернатива нейлону, приемлема при умеренной вибрации и когда кронштейн не находится в непосредственном контакте с источником вибрации.');

-- 6. Крепление двигателя — температура + вибрация (самое жёсткое сочетание условий)
INSERT INTO application_material_recommendation
(part_application_class_id, operating_condition_id, am_material_group_id, am_technology_id, priority, min_infill_percent, recommended_wall_count, orientation_note, recommendation_source_id, rationale) VALUES
(6, 2, 6, 1, 1, 60, 5, 'Максимальное число стенок, посадочные отверстия под винты печатать с припуском под последующее нарезание/армирование резьбовыми вставками',
   3, 'Сочетание вибрации от двигателя и нагрева до 60-80°C требует материала с высокой температурой тепловой деформации (HDT) и усталостной прочностью одновременно — нейлон предпочтителен перед PETG (HDT PETG ниже, есть риск ползучести под вибронагрузкой при нагреве) и перед PLA (низкий HDT ~55-60°C, недопустим при нагреве).'),
(6, 2, 4, 1, 2, 50, 5, NULL,
   1, 'ASA как альтернатива при недоступности нейлона — приемлемая теплостойкость (HDT ~95°C), но уступает нейлону по усталостной прочности под вибрацией на длинной дистанции.');

-- 7. Стойка шасси — ударная нагрузка при посадке
INSERT INTO application_material_recommendation
(part_application_class_id, operating_condition_id, am_material_group_id, am_technology_id, priority, min_infill_percent, recommended_wall_count, orientation_note, recommendation_source_id, rationale) VALUES
(7, 11, 5, 1, 1, 80, 3, 'Печатать так, чтобы направление удара при посадке было в плоскости слоя, а не перпендикулярно ей',
   1, 'TPU (гибкий эластомер) поглощает ударную энергию при жёсткой посадке за счёт упругой деформации вместо хрупкого разрушения — типовой выбор для амортизирующих элементов шасси в любительских БПЛА.'),
(7, 11, 6, 1, 2, 60, 4, NULL,
   3, 'Жёсткая нейлоновая стойка как альтернатива TPU, когда требуется сохранение геометрии/жёсткости после многократных посадок, а не амортизация за счёт гибкости.');

-- 8. Воздуховод/канал (EDF) — температура + скорость потока
INSERT INTO application_material_recommendation
(part_application_class_id, operating_condition_id, am_material_group_id, am_technology_id, priority, min_infill_percent, recommended_wall_count, orientation_note, recommendation_source_id, rationale) VALUES
(8, 3, 4, 1, 1, 20, 3, 'Внутреннюю поверхность канала желательно печатать с минимальной высотой слоя для снижения аэродинамического сопротивления',
   1, 'ASA переносит нагрев от EDF-двигателя (до 80-100°C у моторного отсека) лучше PLA/PETG и сохраняет геометрию канала без деформации, что критично для сохранения тяги.');

-- 9. Кожух антенны — УФ, требования радиопрозрачности
INSERT INTO application_material_recommendation
(part_application_class_id, operating_condition_id, am_material_group_id, am_technology_id, priority, min_infill_percent, recommended_wall_count, orientation_note, recommendation_source_id, rationale) VALUES
(9, 8, 1, 1, 1, 15, 2, 'Минимальная толщина стенки, тонкостенная печать без металлонаполненных или углепластиковых материалов',
   1, 'PLA — приемлемый выбор для не силовых радиопрозрачных кожухов на короткий срок эксплуатации: не содержит проводящих добавок в отличие от карбон-наполненных материалов (которые экранируют сигнал), простой в печати. Для долгой эксплуатации на улице предпочтительнее PETG/ASA из-за УФ и температурной стабильности PLA.'),
(9, 8, 2, 1, 2, 15, 2, NULL,
   1, 'PETG как более долговечная альтернатива PLA при той же радиопрозрачности (не армирован проводящими волокнами), лучше держит температуру и УФ при длительной эксплуатации на улице.');

-- ============================================================
-- Рекомендации типа принтера по классу детали (габариты)
-- ============================================================

INSERT INTO application_printer_recommendation
(part_application_class_id, printer_type_id, min_build_volume_x_mm, min_build_volume_y_mm, min_build_volume_z_mm, priority, recommendation_source_id, rationale) VALUES
(1, 2, 150, 150, 200, 1, 1, 'Носовые обтекатели малых/средних БПЛА обычно вписываются в 150×150×200 мм — стандартный настольный FDM-принтер (CoreXY или картезианский) достаточен, важнее закрытая камера для ASA/ABS чем большой объём печати.'),
(3, 2, 300, 200, 150, 1, 1, 'Крылья/консоли часто превышают 250 мм по размаху — нужен принтер с увеличенной рабочей областью по X, либо печать секциями со сборкой (что снижает прочность в месте стыка).'),
(4, 5, 150, 150, 50, 1, 3, 'Для нейлоновых винтов с изотропными свойствами предпочтителен SLS-принтер промышленного класса (типа EOS P-серии); при недоступности SLS — крупноформатный FDM с нейлоном как компромисс.'),
(6, 1, 100, 100, 100, 1, 1, 'Крепления двигателя компактные, но требуют закрытой камеры для стабильной печати нейлоном/ASA без расслоения — предпочтителен принтер типа Bambu Lab X1-Carbon с подогреваемой камерой, а не открытый картезианский.');
